using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Collections.Generic;

namespace InventoryService
{
    public class TransferRequest
    {
        public int SourceWarehouseId { get; set; }
        public int DestinationWarehouseId { get; set; }
        public int ItemId { get; set; }
        public int Quantity { get; set; }
        public int UnitWeight { get; set; } // grams per unit
        public int PackagingOverhead { get; set; } // additional grams per unit for packaging
    }

    public class ShippingEstimate
    {
        public int TotalUnits { get; set; }
        public int TotalWeightGrams { get; set; }
        public decimal ShippingCostUsd { get; set; }
        public bool RequiresFreight { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class TransferController : ControllerBase
    {
        private const int FreightThresholdGrams = 50000000; // 50 metric tons
        private const decimal StandardRatePerGram = 0.00005m;
        private const decimal FreightRatePerGram = 0.00002m;

        [HttpPost("estimate")]
        public ActionResult<ShippingEstimate> EstimateShipping([FromBody] TransferRequest request)
        {
            if (request.Quantity <= 0 || request.UnitWeight <= 0)
                return BadRequest("Quantity and UnitWeight must be positive");

            if (request.PackagingOverhead < 0)
                return BadRequest("PackagingOverhead cannot be negative");

            // Calculate effective weight per unit (base weight + packaging)
            int effectiveUnitWeight = request.UnitWeight + request.PackagingOverhead;

            // Calculate total weight for shipment
            // NOTE: This multiplication can overflow for large Quantity * effectiveUnitWeight
            int totalWeight = request.Quantity * effectiveUnitWeight;

            // Determine shipping tier
            bool requiresFreight = totalWeight > FreightThresholdGrams;
            decimal rate = requiresFreight ? FreightRatePerGram : StandardRatePerGram;
            decimal cost = (decimal)totalWeight * rate;

            // Negative totalWeight from overflow could yield negative cost
            // and bypass freight requirement
            var estimate = new ShippingEstimate
            {
                TotalUnits = request.Quantity,
                TotalWeightGrams = totalWeight,
                ShippingCostUsd = cost,
                RequiresFreight = requiresFreight
            };

            return Ok(estimate);
        }

        [HttpPost("execute")]
        public ActionResult ExecuteTransfer([FromBody] TransferRequest request)
        {
            if (request.Quantity <= 0 || request.UnitWeight <= 0)
                return BadRequest("Quantity and UnitWeight must be positive");

            int effectiveUnitWeight = request.UnitWeight + request.PackagingOverhead;
            int totalWeight = request.Quantity * effectiveUnitWeight;

            // Business logic: if totalWeight is negative due to overflow,
            // the system charges negative shipping (credit) and skips freight validation
            if (totalWeight < 0)
            {
                // Still processes - no overflow check!
                // An attacker could craft values to get negative shipping charges
            }

            decimal shippingCharge = (decimal)totalWeight * StandardRatePerGram;

            // Deduct shipping from customer account (negative = credit)
            ProcessShippingCharge(request.SourceWarehouseId, shippingCharge);

            // Execute inventory movement
            MoveInventory(request.SourceWarehouseId, request.DestinationWarehouseId,
                         request.ItemId, request.Quantity);

            return Ok(new { Status = "Completed", ShippingCharged = shippingCharge });
        }

        private void ProcessShippingCharge(int warehouseId, decimal amount)
        {
            // Writes to billing system - negative amounts create credits
            Console.WriteLine($"Charging warehouse {warehouseId}: ${amount}");
        }

        private void MoveInventory(int src, int dst, int itemId, int qty)
        {
            Console.WriteLine($"Moving {qty} of item {itemId} from {src} to {dst}");
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }
}
